-- 信用卡推薦：大家共用的卡片庫（每張卡在海外／日本的回饋和手續費）＋每個人自己有哪幾張卡。
-- 每一站依類型（餐廳、住宿、購物、交通）算「回饋 − 手續費」最高的卡；開關在「信用卡」頁。
-- 卡片庫不分行程（台灣的卡到哪都一樣），所有登入的人都能看、能改（優惠常換，誰看到就能更新）；刪除只有建立者或任何行程的管理員。

create table if not exists public.card_catalog (
  id text primary key,                        -- 英文代號，例如 cathay-cube
  name text not null,                         -- 國泰世華 CUBE 卡
  short text not null default '',             -- 標籤用的短名：CUBE
  bank text not null default '',
  country text not null default 'tw',         -- 發卡國：us / uk / tw / jp / kr / other（≠ 行程目的地才算出國、才收手續費）
  network text[] not null default '{}',       -- visa / mastercard / amex / jcb / discover / unionpay
  fx_fee numeric(4,2) not null default 1.5,   -- 海外交易手續費 %
  rates jsonb not null default '[]'::jsonb,   -- [{where: overseas|home|jp|kr, kind: all|food|hotel|shop|sight|move, rate: 總回饋%, note, until: YYYY-MM-DD, cond}]
  cap text not null default '',               -- 回饋上限一句話
  conditions text not null default '',        -- 最重要的條件一句話（要登錄、切方案、綁帳戶…）
  source text not null default '',            -- 來源網址
  checked_at date,                            -- 資料查證日期
  created_by uuid,
  updated_by uuid,
  updated_by_name text,
  updated_at timestamptz not null default now()
);
alter table public.card_catalog enable row level security;

drop policy if exists "signed-in read cards" on public.card_catalog;
create policy "signed-in read cards" on public.card_catalog for select to authenticated using (true);
drop policy if exists "signed-in add cards" on public.card_catalog;
create policy "signed-in add cards" on public.card_catalog for insert to authenticated with check (true);
drop policy if exists "signed-in edit cards" on public.card_catalog;
create policy "signed-in edit cards" on public.card_catalog for update to authenticated using (true) with check (true);
drop policy if exists "creator or admin deletes card" on public.card_catalog;
create policy "creator or admin deletes card" on public.card_catalog for delete to authenticated
  using (created_by = auth.uid() or exists (select 1 from public.members where user_id = auth.uid() and role = 'admin'));

create table if not exists public.my_cards (
  user_id uuid not null references auth.users (id) on delete cascade,
  card_id text not null references public.card_catalog (id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (user_id, card_id)
);
alter table public.my_cards enable row level security;
drop policy if exists "own cards" on public.my_cards;
create policy "own cards" on public.my_cards for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- ---------- 起始卡片庫（2026-11-13 查證；優惠常換，網頁上可以直接改） ----------
-- SEED-START
on conflict (id) do nothing;
-- SEED-END
